"use client";

import {
  Bar,
  BarChart,
  CartesianGrid,
  ReferenceArea,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  type TooltipContentProps,
} from "recharts";
import accuracy from "@/lib/accuracy.json";

// Generated by data/site/export_accuracy.py from the validation outputs.
const A = accuracy;

interface RaceRow {
  race: string;
  mae: number;
  mae_grid: number;
  held: boolean;
}

const rows: RaceRow[] = [
  ...A.leave_one_out.per_race.map((r) => ({ ...r, held: false })),
  ...A.held_out.per_race.map((r) => ({ ...r, held: true })),
];
const firstHeld = A.leave_one_out.per_race.length;

function Tip({ active, payload }: Partial<TooltipContentProps<number, string>>) {
  if (!active || !payload?.length) return null;
  const r = payload[0].payload as RaceRow;
  return (
    <div className="tooltip">
      <strong>{r.race}</strong>
      <span>Simulator: off by {r.mae.toFixed(2)} places on average</span>
      <span>Starting grid: off by {r.mae_grid.toFixed(2)}</span>
      <span>{r.held ? "Held out: never used for fitting" : "Leave-one-out: fitted without this race"}</span>
    </div>
  );
}

/** How the model works and how well it predicted real 2024 races. */
export function AccuracySection() {
  const h = A.held_out;
  const loo = A.leave_one_out;
  return (
    <div className="accuracy">
      <p className="example-label">
        Tested by predicting real {A.season} races before using their results.
      </p>
      <div>
        <div className="accuracy-grid">
          <div>
            <dl className="stat-row">
              <div>
                <dt>Finishing order</dt>
                <dd>{h.spearman.toFixed(2)}</dd>
                <p>
                  rank correlation on {h.races} held-out races, against {h.spearman_grid.toFixed(2)} for the
                  starting grid
                </p>
              </div>
              <div>
                <dt>Position error</dt>
                <dd>{h.mae.toFixed(1)}</dd>
                <p>places off per driver on average, against {h.mae_grid.toFixed(1)} for the grid</p>
              </div>
              <div>
                <dt>Interval coverage</dt>
                <dd>{Math.round(h.coverage * 100)}%</dd>
                <p>
                  of real finishes on the held-out races fell inside the predicted 5th–95th percentile range
                  (nominal 90%)
                </p>
              </div>
            </dl>
            <div className="explain">
              <h3>How it works</h3>
              <p>
                Every lap time is built from the driver&apos;s pace, the tire&apos;s compound and age, fuel load and
                race-day form, with traffic, overtakes, pit stops, safety cars and retirements on top. One simulation
                runs the whole 20-car race thousands of times in C++, and the search compares strategies on the
                same randomly drawn races, so differences come from the strategy, not luck.
              </p>
              <h3>How it was tested</h3>
              <p>
                Parameters were fitted on the first {A.train_races} dry races of {A.season}, then the last{" "}
                {h.races} were predicted from the grid, qualifying and earlier races only. On the training races
                each one was also predicted with the model fitted on the others (leave-one-out): there the simulator
                beat the grid in {loo.beats_grid} of {loo.races} races ({loo.mae.toFixed(2)} vs{" "}
                {loo.mae_grid.toFixed(2)} places), a fairer guide than the held-out races, whose grids were unusually
                misleading after penalties.
              </p>
            </div>
          </div>
          <figure className="accuracy-chart">
            <h3 className="chart-title">Average position error per race</h3>
            <ul className="legend">
              <li>
                <i style={{ background: "var(--data)" }} aria-hidden="true" />
                Simulator
              </li>
              <li>
                <i style={{ background: "var(--data-2)" }} aria-hidden="true" />
                Starting grid
              </li>
              <li>Lower is better</li>
            </ul>
            <div style={{ width: "100%", height: 260 }}>
              <ResponsiveContainer>
                <BarChart data={rows} margin={{ top: 18, right: 4, left: -16, bottom: 0 }} barGap={1} barCategoryGap="22%">
                  <CartesianGrid stroke="var(--rule)" vertical={false} />
                  <XAxis
                    dataKey="race"
                    interval={0}
                    angle={-40}
                    textAnchor="end"
                    height={78}
                    tickLine={false}
                    axisLine={{ stroke: "var(--rule-strong)" }}
                    tick={{ fill: "var(--muted)", fontSize: 11 }}
                  />
                  <YAxis
                    tickLine={false}
                    axisLine={false}
                    tick={{ fill: "var(--muted)", fontSize: 12 }}
                    width={40}
                  />
                  <Tooltip content={<Tip />} cursor={{ fill: "var(--wash)" }} isAnimationActive={false} />
                  <ReferenceArea
                    x1={rows[firstHeld].race}
                    x2={rows[rows.length - 1].race}
                    fill="var(--wash)"
                    fillOpacity={1}
                    stroke="var(--rule-strong)"
                    strokeDasharray="3 3"
                    label={{ value: "Held out", position: "insideTop", offset: -14, fill: "var(--ink-2)", fontSize: 12 }}
                  />
                  <Bar dataKey="mae" fill="var(--data)" radius={[3, 3, 0, 0]} isAnimationActive={false} />
                  <Bar dataKey="mae_grid" fill="var(--data-2)" radius={[3, 3, 0, 0]} isAnimationActive={false} />
                </BarChart>
              </ResponsiveContainer>
            </div>
            <figcaption className="chart-sub">
              Leave-one-out races, then the {h.races} held-out races. Finishers only; drivers keep the strategies they
              actually ran.
            </figcaption>
          </figure>
        </div>
      </div>
    </div>
  );
}

/** One-line summary of the held-out results, for the header. */
export const ACCURACY_SUMMARY = {
  spearman: A.held_out.spearman,
  mae: A.held_out.mae,
};
